function findFirstMultipleOfFour(start, end) {
  for (let number = start; number <= end; number += 1) {
    if (number % 4 === 0) return number;
  }
  return -1;
}

function sumExcept(limit, excluded) {
  let total = 0;
  for (let number = 1; ; number += 1) {
    if (number === excluded) continue;
    if (total + number > limit) break;
    total += number;
  }
  return total;
}
